\mathrm{df\text{-}metric\text{-}open\text{-}family}\vdash\;\begin{aligned}
\mathsf{OpenFam}_{\mathcal A}(C)&\leftrightarrow\mathsf{Met}(\mathcal A)\land C\subseteq[N\times_N(A\times_N\mathbb Q_c^+)]\times_N N,\\
\mathsf{Cover}_{\mathcal A}(C)&\leftrightarrow\mathsf{OpenFam}_{\mathcal A}(C)\land\forall x(\mathsf{Pt}_{\mathcal A}(x)\to\exists i\;x\in_{\mathcal A}(C)_i),\\
\mathsf{DenseOpen}_{\mathcal A}(U)&\leftrightarrow\mathsf{OpenCode}_{\mathcal A}(U)\land\forall a\in A\forall r\in\mathbb Q_c^+\exists x[\mathsf{Pt}_{\mathcal A}(x)\land\delta_{\mathcal A}(x,\widehat a_{\mathcal A})<_R\widehat r\land x\in_{\mathcal A}U],\\
\mathsf{NoIso}(\mathcal A)&\leftrightarrow\mathsf{Met}(\mathcal A)\land\forall x\forall k[\mathsf{Pt}_{\mathcal A}(x)\to\exists y(\mathsf{Pt}_{\mathcal A}(y)\land\neg(x=_{\mathcal A}y)\land\delta_{\mathcal A}(x,y)<_R\widehat{\varepsilon_k})].
\end{aligned}
